INSERT INTO produtos_dtc (nome, descricao, preco, shopify_variant_id, ativo) VALUES ('Carregador Turbo Tipo C 18W - EZRA CZ-P42', 'Carregador turbo tipo C de alta performance da marca EZRA, modelo CZ-P42, com potência de 18W para carregamento rápido e eficiente. Entrada: 100-240V. Saída: 5V/3A, 9V/2A, 12V/1.5A (Power Delivery). Proteção contra sobrecarga, sobretensão e curto-circuito. Design compacto em branco.', 45.90, '47711004360942', true);